#ifndef ONLINE_JUDGE
#define debug(...) std::cerr << __LINE__ << ": [", __DEBUG_UTIL__::printer(#__VA_ARGS__, __VA_ARGS__)
#define debugArr(...) std::cerr << __LINE__ << ": [", __DEBUG_UTIL__::printerArr(#__VA_ARGS__, __VA_ARGS__)
#else
#define debug(...)
#define debugArr(...)
#endif

struct Node {
    long long t;
    int u;
    int mask;
    Node(long long _t, int _u, int _mask) : t(_t), u(_u), mask(_mask) {}
};

struct Cmp {
    bool operator()(const Node &a, const Node &b) const {
        return a.t > b.t;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m, k, l;
    cin >> n >> m >> k >> l;

    vector<int> masks(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        int cnt; cin >> cnt;
        int mask = 0;
        for (int j = 0; j < cnt; ++j) {
            int t; cin >> t;
            if (t >= 1 && t <= k) mask |= (1 << (t - 1));
        }
        masks[i] = mask;
    }

    vector<vector<pair<int,int>>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w; cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    int maxmask = 1 << k;
    const long long INF = (1LL << 60);
    vector<vector<long long>> dist(n + 1, vector<long long>(maxmask, INF));

    priority_queue<Node, vector<Node>, Cmp> pq;
    int start_mask = masks[1];
    dist[1][start_mask] = 0;
    pq.push(Node(0, 1, start_mask));

    while (!pq.empty()) {
        Node cur = pq.top(); pq.pop();
        long long d = cur.t; int u = cur.u; int mask = cur.mask;
        if (d != dist[u][mask]) continue;
        if (u == n && __builtin_popcount(mask) >= l) {
            cout << d << '\n';
            return 0;
        }

        for (auto &e : adj[u]) {
            int v = e.first;
            int w = e.second;
            int nmask = mask | masks[v];
            if (dist[v][nmask] > d + w) {
                dist[v][nmask] = d + w;
                pq.push(Node(dist[v][nmask], v, nmask));
            }
        }
    }

    long long ans = INF;
    for (int mask = 0; mask < maxmask; ++mask) {
        if (__builtin_popcount(mask) >= l) ans = min(ans, dist[n][mask]);
    }

    if (ans == INF) cout << -1 << '\n';
    else cout << ans << '\n';
}
